CREATE VIEW ${schema}.session_last_events WITH (security_invoker=true) AS SELECT DISTINCT ON(session_id) session_id,screen_code,event_type_id,occurred_at,trace_code FROM ${schema}.navigation_events ORDER BY session_id,occurred_at DESC,id DESC;
CREATE VIEW ${schema}.screen_durations WITH (security_invoker=true) AS SELECT screen_code,count(*) AS event_count,sum(duration_ms) AS total_duration_ms,avg(duration_ms)::numeric(18,2) AS average_duration_ms FROM ${schema}.navigation_events WHERE duration_ms IS NOT NULL GROUP BY screen_code;
CREATE VIEW ${schema}.error_terminated_sessions WITH (security_invoker=true) AS SELECT last.session_id,last.screen_code,last.occurred_at FROM ${schema}.session_last_events last JOIN ${schema}.navigation_event_types t ON t.id=last.event_type_id WHERE t.event_category='error';
CREATE VIEW ${schema}.trace_timeline WITH (security_invoker=true) AS SELECT trace_code,occurred_at,'navigation'::text AS source,screen_code AS detail FROM ${schema}.navigation_events WHERE trace_code IS NOT NULL UNION ALL SELECT trace_code,occurred_at,'error'::text,NULL::text FROM ${schema}.error_occurrences UNION ALL SELECT trace_code,occurred_at,'audit'::text,action_code FROM ${schema}.audit_events WHERE trace_code IS NOT NULL;
CREATE VIEW ${schema}.audit_support WITH (security_invoker=true) AS SELECT id,occurred_at,action_code,entity_type,result_code,correlation_id,trace_code,details->>'reason_code' AS reason_code FROM ${schema}.audit_events;
REVOKE ALL ON ALL TABLES IN SCHEMA ${schema} FROM PUBLIC;
